using System.IO;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Documents;
using System.Windows.Input;
using System.Windows.Media;
using Eluna.App.Controls;
using Eluna.App.Models;

namespace Eluna.App.Services;

internal static class ComposerVerification
{
    private static void Check(bool ok, string message) { if (!ok) { throw new InvalidOperationException(message); } }
    private static IEnumerable<T> Find<T>(DependencyObject root) where T : DependencyObject
    { for (int i = 0; i < VisualTreeHelper.GetChildrenCount(root); i++) { DependencyObject child = VisualTreeHelper.GetChild(root, i); if (child is T item) { yield return item; } foreach (T nested in Find<T>(child)) { yield return nested; } } }
    internal static async Task RunAsync(AppStore store, string output)
    {
        Directory.CreateDirectory(output); MainWindow? main = null; using var stop = new CancellationTokenSource(TimeSpan.FromMinutes(5)); CancellationToken token = stop.Token;
        async Task Until(Func<bool> condition) { while (!condition()) { await Task.Delay(25, token); } }
        try
        {
            UnsavedChanges.Review = _ => false; main = new MainWindow(store) { ShowActivated = false, WindowStartupLocation = WindowStartupLocation.Manual, Left = -20000, Top = -20000 }; main.Show(); var chat = main.ViewModel; await Until(() => chat.IsReady || chat.HasError); Check(chat.IsReady, chat.Error);
            var peer = new AgentAccount(Guid.NewGuid(), "星乃", "星", Specialty: "読書と天文学の話をする仲間"); await chat.SaveAgentAsync(peer); Conversation first = await chat.CreateRoomAsync("夜更かしラウンジ", "dm", [peer.Id]); var input = (TextBox)main.FindName("InputBox");
            chat.Input = "前😀後"; input.Select(1, 2); main.OpenEmojiPicker((Button)main.FindName("EmojiButton")); EmojiPicker panel = main.OpenEmojiPanel ?? throw new InvalidOperationException("Picker did not open."); panel.Search.Text = "coffee"; panel.ChooseSelected(); Check(chat.Input == "前☕後" && input.SelectionStart == 2 && input.SelectionLength == 0, "Emoji picker did not replace the native selection/caret correctly."); input.Undo(); Check(chat.Input == "前😀後", "Emoji insertion broke native Undo."); input.Redo(); Check(chat.Input == "前☕後", "Emoji insertion broke native Redo.");
            await Until(() => chat.Settings.RecentEmoji?.Contains("☕") == true); chat.Input = "前の案と次の案"; input.Select(1, 2); Check(main.FormatSelection("bold") && chat.Input == "前**の案**と次の案" && input.SelectedText == "の案", "Formatting did not preserve the selected Japanese text."); Check(main.FormatSelection("bold") && chat.Input == "前の案と次の案", "Repeated formatting did not toggle its delimiters."); input.Undo(); Check(chat.Input == "前**の案**と次の案", "Formatting did not remain a native Undo unit.");
            chat.Input = "一行\r\n二行\r\n三行"; input.Select(input.Text.IndexOf("二行", StringComparison.Ordinal), 4); Check(main.FormatSelection("quote") && chat.Input == "一行\r\n> 二行\r\n三行", "Quotation split a native CRLF or formatted the next line.");
            chat.Input = ""; input.Select(0, 0); main.FormatSelection("block"); Check(chat.Input == "```" + Environment.NewLine + Environment.NewLine + "```" && input.SelectionStart == 3 + Environment.NewLine.Length, "Code block did not put the native caret inside the fence.");
            chat.Input = "元の下書き"; input.Select(0, 0); main.OpenEmojiPicker((Button)main.FindName("EmojiButton")); panel = main.OpenEmojiPanel!; chat.Input = "更新された下書き"; panel.Search.Text = "moon"; panel.ChooseSelected(); Check(chat.Input == "更新された下書き" && main.ActiveToast?.Message.Contains("変わった", StringComparison.Ordinal) == true, "A stale picker overwrote a concurrently updated draft.");
            main.OpenEmojiPicker((Button)main.FindName("EmojiButton")); panel = main.OpenEmojiPanel!; Conversation other = await chat.CreateRoomAsync("今日の予定", "group", [peer.Id]); chat.Input = "別の下書き"; panel.ChooseSelected(); Check(main.OpenEmojiPanel is null && chat.Input == "別の下書き" && first.Draft == "更新された下書き", "Navigation left a picker able to modify another draft.");
            chat.SelectedConversation = first; chat.Input = ""; var message = new ChatMessage { Role = "user", Content = "**太字** · *斜体* · ~~旧案~~ · `code` · \\*記号\\*", Identity = new(null, chat.Self.Name, chat.Self.Icon, Time: DateTimeOffset.Now) }; first.Messages.Add(message);
            await PrototypePreview.RenderAsync(main, Path.Combine(output, "formatting-and-drafts.png")); MarkdownView renderer = Find<MarkdownView>(main).Single(v => ReferenceEquals(v.DataContext, message)); RichTextBox reader = Find<RichTextBox>(renderer).First(); string rendered = new TextRange(reader.Document.ContentStart, reader.Document.ContentEnd).Text;
            Check(!renderer.PlainText && rendered.Contains("太字", StringComparison.Ordinal) && !rendered.Contains("**", StringComparison.Ordinal) && rendered.Contains("*記号*", StringComparison.Ordinal) && message.Content.Contains("**太字**", StringComparison.Ordinal), "Peer Markdown was not rendered losslessly or escaped text became formatting."); Check(reader.Document.Blocks.OfType<Paragraph>().SelectMany(p => p.Inlines).OfType<Span>().Any(s => s.TextDecorations?.Any(d => d.Location == TextDecorationLocation.Strikethrough) == true), "Strikethrough was not displayed.");
            var messages = (ListBox)main.FindName("MessagesList"); var messageRow = (ListBoxItem)messages.ItemContainerGenerator.ContainerFromItem(message);
            main.OpenEmojiPicker(messageRow, message.Id); panel = main.OpenEmojiPanel!; panel.Search.Text = "books"; panel.ChooseSelected(); await Until(() => first.Experience.Reactions?.Any(r => r.Message == message.Id && r.Emoji == "📚") == true);
            main.OpenEmojiPicker(messageRow, message.Id); panel = main.OpenEmojiPanel!; panel.Search.Text = "books"; Check(panel.Choices.Items.OfType<EmojiChoice>().Single().Selected, "Reaction picker lost the selected state."); panel.ChooseSelected(); await Until(() => first.Experience.Reactions?.Any(r => r.Message == message.Id && r.Emoji == "📚") != true); await Until(() => chat.Settings.RecentEmoji?.Contains("📚") == true);
            messageRow.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Right) { RoutedEvent = UIElement.PreviewMouseUpEvent }); Check(messageRow.ContextMenu?.Items.Count > 0, "Message row did not expose its context menu."); messageRow.ContextMenu!.IsOpen = false;
            var messageMenuKey = new KeyEventArgs(Keyboard.PrimaryDevice, PresentationSource.FromVisual(main)!, 0, Key.Apps) { RoutedEvent = Keyboard.PreviewKeyDownEvent }; messageRow.RaiseEvent(messageMenuKey); Check(messageMenuKey.Handled && messageRow.ContextMenu.IsOpen, "Message context menu was not keyboard accessible."); messageRow.ContextMenu.IsOpen = false;
            reader.SelectAll(); reader.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Right) { RoutedEvent = UIElement.PreviewMouseUpEvent }); Check(!messageRow.ContextMenu.IsOpen, "Message actions replaced the native selected-text context menu."); reader.Selection.Select(reader.Document.ContentStart, reader.Document.ContentStart);
            main.ShowDropFeedback(true); foreach (string theme in new[] { "dark", "light" }) { Appearance.Apply(theme, 1.3); main.Width = 820; main.Height = 600; await PrototypePreview.RenderAsync(main, Path.Combine(output, "drop-minimum-" + theme + ".png")); }
            main.HideDropFeedback();
            string file = Path.Combine(store.Root, "資料.txt"); await File.WriteAllTextAsync(file, "今回の会話で読む資料です。", token); Task attach = main.AttachDroppedFilesAsync([file]); chat.SelectedConversation = other; await attach; Check(first.DraftAttachments.Count == 1 && other.DraftAttachments.Count == 0 && first.HasDraft && main.ActiveToast?.Message.Contains(first.Title, StringComparison.Ordinal) == true, "Dropped files or feedback used the currently viewed room instead of the captured target.");
            await main.ArchiveWithUndoAsync(first); Check(first.IsArchived, "Archive action did not apply."); ToastPanel undo = main.ActiveToast!; undo.UndoButton.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent)); await Until(() => undo.UndoButton.Visibility == Visibility.Collapsed); Check(!first.IsArchived && chat.SelectedConversation == other, "Undo restored the wrong room or changed navigation.");
            await main.ArchiveWithUndoAsync(first); undo = main.ActiveToast!; await chat.ToggleArchiveAsync(first); await undo.UndoAsync(); Check(!first.IsArchived && undo.Message.Contains("その後", StringComparison.Ordinal), "A stale undo overwrote a later change.");
            int calls = 0; main.ShowToast("古い通知", () => { calls++; return Task.CompletedTask; }); ToastPanel replaced = main.ActiveToast!; main.ShowToast("新しい通知"); await replaced.UndoAsync(); await replaced.DismissAsync(); Check(calls == 0 && main.ActiveToast?.Message == "新しい通知", "Replaced feedback still had an active undo/dismiss callback.");
            var picker = new EmojiPicker(["☕", "👍"], new HashSet<string> { "👍" }); var host = new Window { Content = picker, Width = 390, Height = 480, ShowActivated = false, WindowStartupLocation = WindowStartupLocation.Manual, Left = -20000, Top = -20000 }; Appearance.Attach(host); host.Show();
            foreach (string theme in new[] { "dark", "light" }) { Appearance.Apply(theme, 1.3); Find<ComboBox>(picker).Single().SelectedValue = "all"; picker.Search.Text = ""; await PrototypePreview.RenderAsync(host, Path.Combine(output, "emoji-" + theme + ".png")); Check(picker.Choices.ActualHeight > 150, "Emoji picker left no usable choice grid."); }
            picker.Search.Text = "存在しない"; Check(picker.Choices.Items.Count == 0, "Unknown emoji search did not show an empty state."); int picked = 0; picker.Picked += _ => picked++; picker.Search.Text = "ありがとう"; var ime = new KeyEventArgs(Keyboard.PrimaryDevice, PresentationSource.FromVisual(host)!, 0, Key.ImeProcessed) { RoutedEvent = Keyboard.PreviewKeyDownEvent }; picker.Search.RaiseEvent(ime); Check(picked == 0, "IME-processed key selected an emoji."); picker.ChooseSelected(); Check(picked == 1, "Keyboard selection did not choose its emoji."); host.Close();
            chat.SelectedConversation = other; Appearance.Apply("dark", 1); main.Width = 1280; main.Height = 900; await PrototypePreview.RenderAsync(main, Path.Combine(output, "navigation-details.png")); Button member = Find<Button>(main).First(b => b.IsVisible && b.DataContext is MemberCard c && c.Account.Id == peer.Id); member.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Right) { RoutedEvent = UIElement.PreviewMouseRightButtonUpEvent }); Check(member.ContextMenu?.Items.OfType<MenuItem>().Any(i => i.Header is "メッセージ") == true, "Member context menu did not expose DM navigation."); member.ContextMenu!.IsOpen = false;
            var menuKey = new KeyEventArgs(Keyboard.PrimaryDevice, PresentationSource.FromVisual(main)!, 0, Key.Apps) { RoutedEvent = Keyboard.PreviewKeyDownEvent }; member.RaiseEvent(menuKey); Check(menuKey.Handled && member.ContextMenu.IsOpen, "Member menu was not keyboard accessible."); member.ContextMenu.IsOpen = false;
            var history = (ListBox)main.FindName("HistoryList"); var historyRow = (ListBoxItem)history.ItemContainerGenerator.ContainerFromItem(first); historyRow.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Right) { RoutedEvent = UIElement.PreviewMouseDownEvent }); historyRow.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Right) { RoutedEvent = UIElement.PreviewMouseUpEvent }); Check(chat.SelectedConversation == other && historyRow.ContextMenu?.Items.OfType<MenuItem>().Any(i => i.Header is "アーカイブ") == true, "Channel context changed navigation or lacked its actions."); historyRow.ContextMenu!.IsOpen = false;
            main.ShowToast("「夜更かしラウンジ」のピン留めを変更しました。", () => Task.CompletedTask); foreach (string theme in new[] { "dark", "light" }) { Appearance.Apply(theme, 1.3); main.Width = 820; main.Height = 600; await PrototypePreview.RenderAsync(main, Path.Combine(output, "feedback-minimum-" + theme + ".png")); Check(main.ActiveToast!.ActualWidth <= 400 && main.ActiveToast.ActualHeight < 180, "Feedback obscured the composer at minimum size."); }
            chat.Input = "一行\r\n二行\r\n三行\r\n四行\r\n五行"; await PrototypePreview.RenderAsync(main, Path.Combine(output, "feedback-expanded-input.png")); var composer = (FrameworkElement)main.FindName("ComposerArea"); Check(main.ActiveToast!.TranslatePoint(new Point(0, main.ActiveToast.ActualHeight), main).Y < composer.TranslatePoint(new Point(0, 0), main).Y, "Feedback covered an expanded multiline composer.");
            await main.ActiveToast!.DismissAsync(); Check(main.ActiveToast is null, "Dismissed feedback stayed attached."); await chat.PersistSafelyAsync(); AppState saved = await store.LoadAsync(); AppStore.Validate(saved); Check(saved.Settings.RecentEmoji?.Contains("☕") == true && saved.Conversations.Single(c => c.Id == first.Id).DraftAttachments?.Count == 1, "Composer preferences or attachment draft did not persist.");
            await File.WriteAllTextAsync(Path.Combine(output, "result.txt"), "Composer: emoji/native caret/Undo/Redo/IME guard/stale draft/navigation, formatting/CRLF/Markdown source, captured file drop, archive undo/stale undo/replacement, member context, themes/minimum/130%, persistence: OK", token);
        }
        catch (Exception ex) { Environment.ExitCode = 1; await File.WriteAllTextAsync(Path.Combine(output, "result.txt"), ex.ToString()); }
        finally { if (main is not null) { foreach (Window child in main.OwnedWindows.Cast<Window>().ToArray()) { child.Close(); } await main.ViewModel.ShutdownAsync(); main.Close(); } Application.Current.Shutdown(); }
    }
}
